-- Verificação consolidada do esquema em produção (migrations 0001–0038). Somente leitura.
-- Esperado: todas as linhas PASS e "== TOTAL ==" com 31 de 31.
with checks as (
  select '0001 fundação: organizacoes, membros, auditoria' item, (select count(*) from pg_tables where schemaname='public' and tablename in ('organizacoes','organizacao_membros','auditoria')) = 3 ok
  union all select '0002 contas + vw_saldo_contas', exists (select 1 from pg_views where viewname='vw_saldo_contas')
  union all select '0004 categorias', exists (select 1 from pg_tables where schemaname='public' and tablename='categorias')
  union all select '0005 lançamentos: motor (5 funções, definer) e movimentos', (select count(*) from pg_proc where proname in ('criar_lancamento','atualizar_lancamento','efetivar_lancamento','cancelar_lancamento','excluir_lancamento') and prosecdef) = 5 and exists (select 1 from pg_tables where tablename='movimentos')
  union all select '0006/0007 negócios e pessoas nos lançamentos', (select count(*) from information_schema.columns where table_schema='public' and table_name='lancamentos' and column_name in ('negocio_id','pessoa_id','contrato_id')) = 3
  union all select '0008 contratos com as colunas do repositório', (select count(*) from information_schema.columns where table_schema='public' and table_name='contratos' and column_name in ('organizacao_id','negocio_id','pessoa_id','plano_id','codigo','valor','periodicidade','data_inicio','data_fim','dia_vencimento','status')) = 11
  union all select '0009 faturamento (colunas + funções + tabelas)', (select count(*) from information_schema.columns where table_schema='public' and table_name='contratos' and column_name in ('faturamento_automatico','faturar_desde','conta_id')) = 3 and (select count(*) from pg_proc where proname in ('faturar_contrato','gerar_faturamento_agora','gerar_faturamento_todas')) = 3 and (select count(*) from pg_tables where tablename in ('faturamentos','faturamento_execucoes')) = 2
  union all select '0011 importação', (select count(*) from pg_proc where proname in ('importar_clientes','nome_plano_importado','data_importada')) = 3
  union all select '0012 recorrências (colunas, trigger, motor com 17 parâmetros)', (select count(*) from information_schema.columns where table_schema='public' and table_name='lancamentos' and column_name in ('recorrente','periodicidade','numero_parcelas','parcela_atual','data_fim_recorrencia','lancamento_origem_id')) = 6 and exists (select 1 from pg_trigger where tgname='lancamentos_b_recorrencia') and (select count(*) from pg_proc where proname in ('criar_lancamento','atualizar_lancamento') and pronargs = 17) = 2
  union all select '0013 apps: tabelas com organizacao_id, funções e views', (select count(*) from information_schema.columns where table_schema='public' and column_name='organizacao_id' and table_name in ('carteira','apps_catalogo','transacoes_carteira')) = 3 and (select count(*) from pg_proc where proname in ('configurar_carteira','criar_app','recarregar_carteira','ativar_app')) = 4 and (select count(*) from pg_views where viewname in ('vw_carteira_resumo','vw_contratos_app')) = 2
  union all select '0030 carteira com dois saldos (dinheiro e crédito, sem taxa fixa)', (select count(*) from information_schema.columns where table_schema='public' and table_name='carteira' and column_name in ('saldo_dinheiro','saldo_credito')) = 2 and exists (select 1 from information_schema.columns where table_schema='public' and table_name='negocios' and column_name='usa_carteira') and (select count(*) from information_schema.columns where table_schema='public' and table_name='negocios' and column_name in ('tipo_saldo','taxa_conversao')) = 0
  union all select '0014 sem funções antigas do motor (só 1 assinatura de cada)', (select count(*) from pg_proc where proname in ('criar_lancamento','atualizar_lancamento')) = 2
  union all select '0014 sem objetos externos', not exists (select 1 from pg_proc where proname in ('recarregar_saldo','trigger_auditoria','atualizar_updated_at_carteira')) and not exists (select 1 from pg_views where viewname='vw_dashboard_apps') and not exists (select 1 from information_schema.columns where table_schema='public' and table_name in ('carteira','apps_catalogo','transacoes_carteira') and column_name in ('created_at','updated_at'))
  union all select '0016 notificações (tabelas, motor, view)', (select count(*) from pg_tables where schemaname='public' and tablename in ('notificacoes_config','notificacoes_log')) = 2 and (select count(*) from pg_proc where proname in ('gerar_notificacoes','processar_notificacoes','executar_notificacoes_agora','enviar_notificacao_teste')) = 4 and exists (select 1 from pg_views where viewname='vw_notificacoes')
  union all select '0018 provedor evolution (fila só para service_role)', (select count(*) from pg_proc where proname in ('notificacoes_para_envio','registrar_resultado_notificacao')) = 2 and not exists (select 1 from information_schema.routine_privileges where routine_name in ('notificacoes_para_envio','registrar_resultado_notificacao') and grantee in ('anon','authenticated','PUBLIC'))
  union all select '0023 portal do cliente (tabelas, funções, anon restrito)', (select count(*) from pg_tables where schemaname='public' and tablename in ('portal_config','portal_acessos','promocoes','indicacoes','descontos_contrato')) = 5 and (select count(*) from pg_proc where proname like 'portal\_%') >= 12 and (select count(*) from information_schema.routine_privileges where grantee='anon' and routine_name like 'portal\_%') = 2
  union all select '0024 portal servnet (login sem senha, fidelidade, chamados, status da rede)', (select count(*) from pg_tables where schemaname='public' and tablename in ('portal_status_rede','portal_solicitacoes','portal_login_tentativas')) = 3 and (select count(*) from pg_proc where proname in ('fidelidade_cartao','fidelidade_registrar_premio','portal_login_verificar','portal_vincular_servico','portal_fidelidade','portal_solicitar')) = 6 and exists (select 1 from information_schema.columns where table_name='pessoas' and column_name='data_nascimento')
  union all select '0025 recorrência fixa/parcelada (tipo_recorrencia)', exists (select 1 from information_schema.columns where table_name='lancamentos' and column_name='tipo_recorrencia') and (select count(*) from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='tipo_recorrencia') = 2 and exists (select 1 from pg_proc p where p.proname='tg_lancamentos_recorrencia' and pg_get_functiondef(p.oid) like '%tipo_recorrencia%')
  union all select '0026 baixa parcial', exists (select 1 from pg_proc where proname='baixar_parcial') and not exists (select 1 from information_schema.routine_privileges where routine_name='baixar_parcial' and grantee in ('anon','PUBLIC'))
  union all select '0027 contratos de despesa (fornecedor) + lançamento automático ao criar', exists (select 1 from information_schema.columns where table_name='contratos' and column_name='tipo_financeiro') and exists (select 1 from information_schema.columns where table_name='negocios' and column_name='categoria_despesa_id') and exists (select 1 from pg_trigger where tgname='contratos_c_faturar_ao_criar')
  union all select '0028 saldo_inicial_mes', exists (select 1 from pg_proc where proname='saldo_inicial_mes') and not exists (select 1 from information_schema.routine_privileges where routine_name='saldo_inicial_mes' and grantee in ('anon','PUBLIC'))
  union all select '0029 projeção de recorrência + edição em lote', (select count(*) from pg_proc where proname in ('projetar_lancamento','atualizar_lancamento_recorrente','gerar_proxima_parcela_projetada')) = 3 and not exists (select 1 from information_schema.routine_privileges where routine_name='gerar_proxima_parcela_projetada' and grantee in ('anon','authenticated','PUBLIC'))
  union all select '0031 projeção de contratos (derivada, sem gravar)', exists (select 1 from pg_proc where proname='projecao_contratos' and prosecdef) and not exists (select 1 from information_schema.routine_privileges where routine_name='projecao_contratos' and grantee in ('anon','PUBLIC'))
  union all select '0032 edição de data em recorrência (6 parâmetros)', (select count(*) from pg_proc where proname='atualizar_lancamento_recorrente' and pronargs = 6) = 1
  union all select '0033 periodicidades de contrato (6 valores no enum)', (select count(*) from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='periodicidade') = 6
  union all select '0034 reancoragem de vencimento no pagamento atrasado', exists (select 1 from pg_proc where proname='reancorar_recorrencia') and not exists (select 1 from information_schema.routine_privileges where routine_name='reancorar_recorrencia' and grantee in ('anon','authenticated','PUBLIC'))
  union all select '0035 excluir parcela exclui a cadeia prevista', exists (select 1 from pg_proc p where p.proname='excluir_lancamento' and pg_get_functiondef(p.oid) like '%cadeia%')
  union all select '0036 importação com documento e plano opcionais', exists (select 1 from pg_proc p where p.proname='importar_clientes' and pg_get_functiondef(p.oid) like '%v_doc is not null and not public.documento_valido%')
  union all select '0037 importação só com nome obrigatório', exists (select 1 from pg_proc p where p.proname='importar_clientes' and pg_get_functiondef(p.oid) like '%v_tel is not null and v_tel !~%')
  union all select '0038 cartão de crédito (config, faturas, funções)', (select count(*) from pg_tables where schemaname='public' and tablename in ('cartoes_config','faturas','fatura_itens')) = 3 and (select count(*) from pg_proc where proname in ('fechar_fatura_cartao','fechar_faturas_cartoes','fechar_faturas_agora','pagar_fatura')) = 4 and exists (select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='tipo_conta' and e.enumlabel='credito')
  union all select '0040 encargos ao pagar com atraso', (select count(*) from pg_proc where proname='efetivar_lancamento') = 1 and exists (select 1 from pg_proc p where p.proname='efetivar_lancamento' and pg_get_functiondef(p.oid) like '%p_encargos%')
  union all select '0041 conta escolhida na baixa (efetivar com 4 parâmetros)', (select count(*) from pg_proc where proname='efetivar_lancamento' and pronargs = 4) = 1
  union all select '0042 disparos whatsapp (tabelas, motor, fila service_role)', (select count(*) from pg_tables where schemaname='public' and tablename in ('disparo_modelos','disparos','disparo_itens')) = 3 and (select count(*) from pg_proc where proname in ('criar_disparo','reenviar_falhas_disparo','disparos_para_envio','registrar_resultado_disparo','processar_disparos')) = 5 and not exists (select 1 from information_schema.routine_privileges where routine_name in ('disparos_para_envio','registrar_resultado_disparo') and grantee in ('anon','authenticated','PUBLIC')) and exists (select 1 from information_schema.columns where table_name='pessoas' and column_name='login_servidor')
  union all select '0047 ftth (ctos, portas, histórico, motor)', (select count(*) from pg_tables where schemaname='public' and tablename in ('ctos','cto_portas','cto_historico')) = 3 and (select count(*) from pg_proc where proname in ('vincular_porta_cto','liberar_porta_cto','trocar_porta_cto','defeito_porta_cto')) = 4 and exists (select 1 from pg_views where viewname='vw_ctos_ocupacao')
  union all select '0048 ftth pop e fios (tipo, pop_id, local do cliente)', exists (select 1 from information_schema.columns where table_name='ctos' and column_name='pop_id') and (select count(*) from information_schema.columns where table_name='cto_portas' and column_name in ('cliente_latitude','cliente_longitude')) = 2 and exists (select 1 from pg_proc where proname='local_cliente_porta')
  union all select '0049 ftth rotas com vértices (rota_pop, rota_cliente)', exists (select 1 from information_schema.columns where table_name='ctos' and column_name='rota_pop') and exists (select 1 from information_schema.columns where table_name='cto_portas' and column_name='rota_cliente') and (select count(*) from pg_proc where proname in ('rota_pop_cto','rota_cliente_porta','validar_rota')) = 3
  union all select '0050 endereço em pessoas', exists (select 1 from information_schema.columns where table_name='pessoas' and column_name='endereco')
  union all select '0051 lacre numerado por porta', exists (select 1 from information_schema.columns where table_name='cto_portas' and column_name='lacre') and exists (select 1 from pg_proc where proname='lacre_porta_cto')
  union all select '0052 identificação (lacre) da própria CTO', exists (select 1 from information_schema.columns where table_name='ctos' and column_name='lacre')
  union all select '0068 fechamento de mês (trava do realizado)', exists (select 1 from pg_tables where schemaname='public' and tablename='fechamentos_mes') and (select count(distinct proname) from pg_proc where proname in ('fechar_mes','reabrir_mes','mes_fechado')) = 3
  union all select '0067 patrimônio (bens individuais + histórico)', (select count(*) from pg_tables where schemaname='public' and tablename in ('patrimonios','patrimonio_historico')) = 2
  union all select '0066 indique e ganhe com presente (funções e colunas)', (select count(distinct proname) from pg_proc where proname in ('criar_indicacao_admin','escolher_presente_indicacao','entregar_presente_indicacao','portal_escolher_presente','portal_presentes_indicacao','faixa_presente_indicacao')) = 6 and exists (select 1 from information_schema.columns where table_name='indicacoes' and column_name='presente_item_id')
  union all select '0065 natureza da categoria (operacional × investimento)', exists (select 1 from information_schema.columns where table_name='categorias' and column_name='natureza')
  union all select '0064 excluir pessoa sem histórico', exists (select 1 from pg_proc where proname='excluir_pessoa' and prosecdef)
  union all select '0063 aceite digital do contrato', exists (select 1 from pg_tables where schemaname='public' and tablename='aceites_contrato') and (select count(distinct proname) from pg_proc where proname in ('contrato_texto_termo','registrar_aceite_contrato','portal_meus_aceites')) = 3
  union all select '0062 monitoramento da olt (status, eventos, ping)', (select count(*) from pg_tables where schemaname='public' and tablename in ('olt_status','olt_eventos')) = 2 and exists (select 1 from pg_proc where proname='olt_registrar_ping')
  union all select '0061 ftth ceo + encadeamento (tipo, olt, impacto)', exists (select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='tipo_ponto_rede' and e.enumlabel='ceo') and exists (select 1 from information_schema.columns where table_name='ctos' and column_name='olt_ip') and exists (select 1 from pg_proc where proname='ftth_abaixo_de')
  union all select '0060 bi gerencial (view mensal por negócio)', exists (select 1 from pg_views where schemaname='public' and viewname='vw_bi_mensal_negocio')
  union all select '0059 pix + bloqueio assistido (tabelas, motor, service)', (select count(*) from pg_tables where schemaname='public' and tablename in ('pix_cobrancas','bloqueios')) = 2 and (select count(distinct proname) from pg_proc where proname in ('pix_registrar','pix_confirmar','pix_efetivar_interno','gerar_bloqueios','executar_bloqueio')) = 5 and exists (select 1 from information_schema.columns where table_name='portal_config' and column_name='conta_pix_id')
  union all select '0058 comodato (tabela, motor, OS de recolhimento)', (select count(*) from pg_tables where schemaname='public' and tablename in ('comodatos','comodato_historico')) = 2 and (select count(distinct proname) from pg_proc where proname in ('registrar_comodato','recolher_comodato','trocar_comodato','perda_comodato')) = 4 and exists (select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='tipo_os' and e.enumlabel='recolhimento')
  union all select '0057 portal: visita técnica vira OS + avisos WhatsApp', (select count(distinct proname) from pg_proc where proname in ('portal_abrir_visita','portal_minhas_visitas','portal_responder_remarcacao','portal_avaliar_visita','os_notificar')) = 5 and exists (select 1 from information_schema.columns where table_name='notificacoes_log' and column_name='os_id')
  union all select '0056 técnico: acesso restrito, reposição e fotos', (select count(*) from pg_tables where schemaname='public' and tablename in ('reposicao_solicitacoes','os_fotos')) = 2 and (select count(distinct proname) from pg_proc where proname in ('tecnico_do_usuario','os_info_cliente','solicitar_reposicao','registrar_foto_os')) = 4 and exists (select 1 from pg_policies where tablename='ordens_servico' and policyname='os_do_tecnico')
  union all select '0055 ordens de serviço (tabelas, motor, views)', (select count(*) from pg_tables where schemaname='public' and tablename in ('tecnicos','tecnico_estoque','tecnico_movimentacoes','ordens_servico','os_materiais','os_historico')) = 6 and (select count(distinct proname) from pg_proc where proname in ('abrir_os','encerrar_os','abastecer_tecnico','aprovar_comissao_os')) = 4 and (select count(*) from pg_views where schemaname='public' and viewname in ('vw_os_custo_contrato','vw_bolsa_tecnicos')) = 2
  union all select '0054 estoque instalações + payback (tabela, motor, views)', (select count(*) from pg_tables where schemaname='public' and tablename='estoque_instalacoes') = 1 and (select count(*) from pg_proc where proname='registrar_instalacao') = 1 and (select count(*) from pg_views where schemaname='public' and viewname in ('vw_payback_contrato','vw_estoque_consumo_mensal','vw_estoque_consumo_item')) = 3
  union all select '0053 estoque (tabelas, motor, imutabilidade)', (select count(*) from pg_tables where schemaname='public' and tablename in ('estoque_categorias','estoque_itens','estoque_movimentacoes')) = 3 and (select count(distinct proname) from pg_proc where proname in ('entrada_estoque','saida_estoque','ajuste_estoque')) = 3
  union all select 'RLS ligado em todas as tabelas públicas', (select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r')
)
select item, ok, case when ok then 'PASS' else 'FALHOU' end as resultado from checks
union all select '== TOTAL ==', bool_and(ok), count(*) filter (where ok) || ' de ' || count(*) || ' verificações OK' from checks
order by 1;
